export function localeCode(lang){ return (languageCatalog.find(x=>x.name===lang)||languageCatalog[0]).code; }
export function dictionaryFor(lang){ return D[lang] || D.Hindi; }
const allReverse = (()=>{
  const r={};
  for(const [lang,dict] of Object.entries(D)) for(const [en,val] of Object.entries(dict)) if(val && !r[val]) r[val]=en;
  return r;
})();
const canonicalSet=new Set(Object.keys(D.English));
function canonicalize(value){
  const t=value.trim();
  return allReverse[t] || t;
}
const reverseMaps = {};
for (const locale of Object.keys(D)) {
  reverseMaps[locale] = {};
  for (const [key,value] of Object.entries(D[locale])) reverseMaps[locale][value] = key;
}
function canonicalKey(value, currentLang){
  const v=String(value??'').trim();
  if(!v) return v;
  if(D.English?.[v]) return v;
  const langs=[currentLang,...Object.keys(D).filter(x=>x!==currentLang)];
  for(const lang of langs){ if(reverseMaps[lang]?.[v]) return reverseMaps[lang][v]; }
  return v;
}
export function translateString(value,lang){
  const key=canonicalKey(value,lang);
  return D[lang]?.[key] ?? key;
}
export function installLocaleBridge(lang){
  if(typeof document==='undefined') return ()=>{};
  const root=document.documentElement;
  root.lang=localeCode(lang);
  root.dataset.locale=lang;
  let busy=false;
  const shouldSkip=(node)=>{
    if(!node.parentElement) return true;
    const p=node.parentElement;
    return ['SCRIPT','STYLE','CODE','PRE'].includes(p.tagName) || p.closest('[data-no-translate="true"]');
  };
  const translateNode=(node)=>{
    if(shouldSkip(node)) return;
    const original=node.nodeValue||'';
    const leading=(original.match(/^\s*/)||[''])[0], trailing=(original.match(/\s*$/)||[''])[0];
    const core=original.slice(leading.length, original.length-trailing.length || original.length);
    if(!core.trim()) return;
    const translated=translateString(core,lang);
    if(translated!==core) node.nodeValue=leading+translated+trailing;
  };
  const attrs=['placeholder','title','aria-label'];
  const scan=()=>{
    if(busy) return; busy=true;
    const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
    const nodes=[]; let n; while((n=walker.nextNode())) nodes.push(n);
    nodes.forEach(translateNode);
    document.querySelectorAll('input,button,[title],[aria-label]').forEach(el=>{
      if(el.dataset.noTranslate==='true') return;
      for(const a of attrs){ if(el.hasAttribute(a)){ const v=el.getAttribute(a); const tv=translateString(v,lang); if(tv!==v) el.setAttribute(a,tv); } }
    });
    busy=false;
  };
  scan();
  const observer=new MutationObserver(()=>{ if(!busy) requestAnimationFrame(scan); });
  observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:attrs});
  return ()=>observer.disconnect();
}
